INSERT INTO `bd_flood_events` (`event_id`, `event_name`, `districts`, `start_date`, `end_date`, `confidence`, `flood_type`, `notes`, `source_urls`) VALUES
('BDF-2017-03-HAOR', '2017 early haor flash flood', 'Sylhet;Moulvibazar;Sunamganj;Habiganj;Netrokona;Kishoreganj', '2017-03-28', '2017-04-24', 'medium', 'flash_flood', 'Start 28 Mar per NIRAPAD report quoted by DFO; end approximated from DFO event dates (19-24 Apr)', 'https://floodobservatory.colorado.edu/Events/2017Bangladesh4466/2017Bangladesh4466.html | https://cpd.org.bd/resources/2017/10/Flood-2017-Assessing-Damage-and-Post-flood-Management.pdf'),
('BDF-2017-08-N1', '2017 August northern flood (Teesta/Dharla side)', 'Panchagarh;Thakurgaon;Dinajpur;Nilphamari;Rangpur;Lalmonirhat', '2017-08-12', '2017-08-18', 'medium', 'river_flood', 'Flooding in northern tip since 12 Aug; BSS reported normalcy returning in these districts by 18 Aug', 'https://wp.bssnews.net/?p=3793 | https://www.millenniumpost.in/world/flood-toll-mars-bangladeshs-reputation-for-disaster-management-259011'),
('BDF-2017-08-N2', '2017 August northern flood (Brahmaputra side)', 'Kurigram;Gaibandha', '2017-08-12', '2017-08-24', 'medium', 'river_flood', 'Still improving but inundated through 22-24 Aug per BSS and The Independent', 'https://wp.bssnews.net/?p=3976 | https://theindependentbd.com/arcprint/details/110974/2017-08-24'),
('BDF-2017-08-N3', '2017 August flood (Jamuna side)', 'Bogura;Sirajganj;Jamalpur', '2017-08-15', '2017-08-24', 'low', 'river_flood', 'Start approximated from reports of deaths and rising water 15-17 Aug; end from 24 Aug report', 'https://tds-images.thedailystar.net/tags/bangladesh-flood-2017 | https://theindependentbd.com/arcprint/details/110974/2017-08-24'),
('BDF-2019-07-BJ', '2019 July Brahmaputra-Jamuna flood', 'Kurigram;Gaibandha;Jamalpur;Bogura;Sirajganj;Tangail', '2019-07-10', '2019-07-27', 'medium', 'river_flood', 'Rivers rose from ~10 Jul; water levels still high until 27 Jul per FFWC (Dawn 27 Jul 2019)', 'https://www.dawn.com/news/1496507 | https://reliefweb.int/disaster/fl-2019-000079-bgd | https://watchers.news/2019/07/18/bangladesh-flood-july-2019/'),
('BDF-2019-07-NE', '2019 July north-east flood', 'Sylhet;Sunamganj', '2019-07-13', '2019-07-20', 'low', 'flash_flood', 'Reported flooded in mid-July bulletins; exact end date not found', 'https://today.thefinancialexpress.com.bd/print/flooding-worsens-in-15-districts-1563035406 | https://today.thefinancialexpress.com.bd/print/flooding-worsens-in-north-may-affect-central-part-1563558601'),
('BDF-2020-07-BJ', '2020 July-August second flood wave (Brahmaputra-Jamuna)', 'Kurigram;Gaibandha;Jamalpur;Bogura;Sirajganj', '2020-07-11', '2020-08-07', 'medium', 'river_flood', 'Basin-wide: river crossed danger level 11 Jul, wave lasted until 7 Aug (Copernicus GloFAS case study); individual districts flooded for part of the window', 'https://global-flood.emergency.copernicus.eu/get-involved/case-study-bangladesh-2020 | https://www.ecmwf.int/node/19821 | https://wp.bssnews.net/?p=427109'),
('BDF-2020-07-N', '2020 July flood (Teesta/Dharla side)', 'Lalmonirhat;Nilphamari', '2020-07-11', '2020-07-22', 'low', 'river_flood', 'Above danger mark mid-July; BWDB reported improving by ~23 Jul', 'https://today.thefinancialexpress.com.bd/print/flood-to-worsen-further-in-8-dists-1594661623 | https://wp.bssnews.net/?p=427109'),
('BDF-2022-05-NE', '2022 May north-east flash flood (first wave)', 'Sylhet;Sunamganj', '2022-05-17', '2022-05-24', 'medium', 'flash_flood', 'Began 17 May (WHO, IFRC); water began receding 22 May (Dawn 23 May); some areas stayed flooded a few more days', 'https://dawn.com/news/1691051/millions-marooned-as-worst-floods-in-20-years-ravage-bangladesh | https://www.who.int/bangladesh/news/detail/23-06-2022-bangladesh-flood-2022-who-collaboration-with-dghs-mohfw | https://www.downtoearth.org.in/news/climate-change/four-million-people-affected-by-double-floods-within-a-month-in-bangladesh-s-sylhet-division-83351'),
('BDF-2022-06-N', '2022 June flood (Kurigram, Rangpur division)', 'Kurigram', '2022-06-17', '2022-06-28', 'low', 'river_flood', 'Kurigram named among worst-hit districts (9 upazilas) in the June 2022 floods; start/end approximated from the wider event window', 'https://today.thefinancialexpress.com.bd/print/receding-flood-waters-reveal-extensive-damage-in-sylhet-1656268362 | https://www.globalgiving.org/microprojects/flood-relief-for-bangladesh/reports/'),
('BDF-2022-06-NE', '2022 June north-east flash flood (core districts)', 'Sylhet;Sunamganj;Moulvibazar;Habiganj;Netrokona', '2022-06-15', '2022-06-28', 'medium', 'flash_flood', 'UN/WHO: severe flooding from mid-June; receding reports 27-28 Jun', 'https://bangladesh.un.org/bn/download/110061/188010 | https://www.who.int/bangladesh/news/detail/23-06-2022-bangladesh-flood-2022-who-collaboration-with-dghs-mohfw | https://ifrc.org/press-release/millions-bangladesh-impacted-one-worst-floodings-ever-seen'),
('BDF-2022-06-NE2', '2022 June flash flood (other affected districts)', 'Kishoreganj;Brahmanbaria;Mymensingh;Sherpur', '2022-06-17', '2022-06-28', 'low', 'flash_flood', 'Listed among the 9 affected districts; WHO says wider spread from 17 Jun', 'https://bangladesh.un.org/bn/download/110061/188010 | https://www.who.int/bangladesh/news/detail/23-06-2022-bangladesh-flood-2022-who-collaboration-with-dghs-mohfw'),
('BDF-2023-07-N', '2023 July Teesta/Dudhkumar flood', 'Lalmonirhat;Kurigram', '2023-07-12', '2023-07-15', 'low', 'river_flood', '13 Jul 2023: Teesta 19cm and Dudhkumar 13cm above danger, >10,000 families stranded; exact window approximated', 'https://www.thedailystar.net/news/bangladesh/news/teesta-dudhkumar-water-flow-above-danger-level-3368171'),
('BDF-2023-07-NE', '2023 early July Sylhet/Sunamganj heavy-rain flood', 'Sunamganj;Sylhet', '2023-06-30', '2023-07-05', 'low', 'flash_flood', 'Four days of rain to 2 Jul; Sunamganj town and low areas inundated, Surma above danger on 2 Jul; end date approximated', 'https://www.tbsnews.net/bangladesh/heavy-rains-may-trigger-short-term-flood-sylhet-sunamganj-658738 | https://en.prothomalo.com/bangladesh/local-news/hxuyoaeuek'),
('BDF-2023-08-SE', '2023 August Chattogram division flash flood', 'Chattogram;Coxs Bazar;Bandarban;Rangamati', '2023-08-05', '2023-08-13', 'medium', 'flash_flood', 'Rain from 5 Aug, flash floods 7 Aug; UNOSAT exposure analysis 5-10 Aug; OCHA sitrep as of 13 Aug', 'https://reliefweb.int/disaster/fl-2023-000157-bgd | https://www.adrc.asia/view_disaster_en.php?NationCode=&Lang=en&Key=2632 | https://www.sheltercluster.org/bangladesh-flash-flood-and-monsoon-rain-2023/documents/rapid-assessment-chattogram-division-flash'),
('BDF-2023-08-SE2', '2023 August flash flood (Feni)', 'Feni', '2023-08-07', '2023-08-10', 'low', 'flash_flood', 'ReliefWeb lists Feni among areas submerged on 7 Aug', 'https://reliefweb.int/disaster/fl-2023-000157-bgd'),
('BDF-2024-06-NE', '2024 June Sylhet flash flood (core districts)', 'Sylhet;Sunamganj;Moulvibazar;Habiganj', '2024-06-15', '2024-06-30', 'medium', 'flash_flood', 'Flooding reported mid-June; heavy flooding 20-25 Jun; worsening again by 2 Jul', 'https://global-flood.emergency.copernicus.eu/news/173-flooding-in-bangladesh-may-to-june-2024/ | https://www.unicef.org/media/158381/file/Bangladesh-Humanitarian-SitRep-Sylhet-Floods-15-June-2024.pdf | https://www.acaps.org/en/countries/bangladesh'),
('BDF-2024-06-NE2', '2024 June flash flood (other districts)', 'Kishoreganj;Netrokona', '2024-06-20', '2024-06-27', 'low', 'flash_flood', 'Named as also affected during 20-25 Jun', 'https://global-flood.emergency.copernicus.eu/news/173-flooding-in-bangladesh-may-to-june-2024/'),
('BDF-2024-06-SE', '2024 June south-east flash flood', 'Feni;Rangamati;Khagrachhari;Bandarban;Coxs Bazar', '2024-06-18', '2024-06-20', 'low', 'flash_flood', 'OCHA/BDRCS: significant flooding around 18-19 Jun; end approximated', 'https://reliefweb.int/report/bangladesh/bangladesh-flood-2024-situation-report-01-l-7-july-2024-1400-hrs'),
('BDF-2024-07-BJ', '2024 July Brahmaputra-Jamuna flood (third wave)', 'Kurigram;Gaibandha;Jamalpur;Sirajganj;Bogura', '2024-07-02', '2024-07-18', 'medium', 'river_flood', '19 stations above danger on 9 Jul; Brahmaputra rising again 12 Jul; Kurigram marooned >2 weeks; end approximated', 'https://bssnews.net/news-flash/198519 | https://en.timenewsbd.net/DastU8IUssz2usWf | https://reliefweb.int/report/bangladesh/bangladesh-flood-2024-situation-report-01-l-7-july-2024-1400-hrs | https://www.daily-sun.com/post/757403'),
('BDF-2024-07-NE', '2024 early July north-east flood (third spell)', 'Sylhet;Sunamganj', '2024-07-01', '2024-07-08', 'low', 'flash_flood', 'BSS 4 Jul 2024: third spell of flood, large parts of Sylhet and Sunamganj submerged; end approximated', 'https://bssnews.net/news-flash/198519'),
('BDF-2024-07-T', '2024 July Jamuna flood (Tangail)', 'Tangail', '2024-07-04', '2024-07-14', 'low', 'river_flood', 'Jamuna 83cm and Dhaleshwari 155cm above danger in Tangail (TBS); window approximated', 'https://www.tbsnews.net/node/111385 | https://bssnews.net/news-flash/198519'),
('BDF-2024-08-SE', '2024 August eastern flash flood', 'Feni;Cumilla;Chattogram;Khagrachhari;Noakhali;Moulvibazar;Habiganj;Brahmanbaria;Sylhet;Lakshmipur;Coxs Bazar', '2024-08-20', '2024-08-30', 'medium', 'flash_flood', 'Started 20 Aug (some reports 19 Aug); improving by 29-30 Aug; severity varied by district', 'https://today.thefinancialexpress.com.bd/print/floods-death-toll-rises-to-31-over-58m-affected-1724867124 | https://bdrcs.org/wp-content/uploads/2024/08/BDRCS-Sitrep-3-Southeastern-Flood-August-2024.pdf | https://appliedsciences.nasa.gov/what-we-do/disasters/disasters-activations/bangladesh-flooding-august-2024'),
('BDF-2025-08-N', '2025 August Teesta flood (Lalmonirhat)', 'Lalmonirhat', '2025-08-13', '2025-08-15', 'low', 'river_flood', '14 Aug 2025: ~10,000 families marooned as Teesta flows above danger at Dalia', 'https://www.jagonews24.com/en/national/news/84808'),
('BDF-2025-09-N', '2025 September Teesta/Jamuna rise', 'Lalmonirhat;Kurigram;Gaibandha;Rangpur;Nilphamari', '2025-09-14', '2025-09-17', 'low', 'river_flood', '15 Sep 2025 Teesta above danger, all 44 gates opened; several rivers above danger on 16 Sep; inundation reports limited', 'https://www.dhakatribune.com/bangladesh/nation/391508/teesta-flows-above-danger-mark-all-sluicegates | https://www.banglanews24.com/english/national/news/bd/150679.details'),
('BDF-2025-10-N', '2025 October Teesta flood', 'Lalmonirhat;Rangpur;Nilphamari;Kurigram', '2025-10-05', '2025-10-09', 'medium', 'river_flood', 'Teesta 10cm above danger at Dalia on 6 Oct; low-lying areas flooded; ~20,000 stranded in Lalmonirhat; falling trend from 7 Oct', 'https://www.dhakatribune.com/bangladesh/nation/393367/low-lying-areas-flooded-in-rangpur-as-teesta | https://www.tbsnews.net/bangladesh/flood-inundates-low-lying-areas-lalmonirhat-20000-people-marooned-1253911'),
('BDF-2026-04-NE', '2026 late-April Netrokona/Moulvibazar flood', 'Netrokona;Moulvibazar', '2026-04-29', '2026-05-01', 'low', 'flash_flood', 'FFWC 29 Apr 2026: four rivers above danger, flooding ongoing in Netrokona and Moulvibazar; heavy rain forecast to 1 May', 'https://www.thedailystar.net/news/environment/climate-crisis/natural-disaster/news/water-levels-four-rivers-above-danger-level-flood-risk-five-districts-4163701 | https://www.jagonews24.com/en/national/news/92274'),
('BDF-2026-07-MK', '2026 July Manikganj flash flood', 'Manikganj', '2026-07-04', '2026-07-10', 'low', 'flash_flood', 'At least 301mm of rain fell 4-10 Jul; crops damaged on 222 ha (BSS 29 Jul)', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-NE', '2026 July Moulvibazar/Habiganj flood (Khowai embankment breach 9 Jul)', 'Moulvibazar;Habiganj', '2026-07-09', '2026-07-21', 'medium', 'flash_flood', 'IFRC lists both among the most affected districts; Khowai embankment collapsed ~9 Jul; Habiganj waters receded by 25 Jul', 'https://go.ifrc.org/field-reports/18466 | https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-NE2', '2026 late-July Kushiyara/Surma flood', 'Sylhet', '2026-07-20', '2026-07-27', 'medium', 'flash_flood', 'FFWC 20 Jul: Kushiyara 33cm above danger at Fenchuganj; still above danger on 27 Jul, improving', 'https://www.thedailystar.net/news/environment/news/ffwc-warns-flash-floods-ten-districts-within-next-24-48-hours-4228486 | https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-NK', '2026 July Someshwari overflow', 'Netrokona', '2026-07-20', '2026-07-22', 'low', 'flash_flood', 'Someshwari 19cm above danger at Kalmakanda, low-lying areas inundated (FFWC 20 Jul)', 'https://www.thedailystar.net/news/environment/news/ffwc-warns-flash-floods-ten-districts-within-next-24-48-hours-4228486'),
('BDF-2026-07-SE', '2026 July south-east flash flood and landslides (core)', 'Chattogram;Coxs Bazar;Bandarban;Rangamati;Khagrachhari', '2026-07-06', '2026-07-21', 'medium', 'flash_flood', 'Record 412mm in Chattogram on 7 Jul; agriculture ministry assessed the 7-19 Jul rains; Chattogram remained worst hit on 25 Jul; ~1.07-1.28 million affected', 'https://go.ifrc.org/field-reports/18466 | https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-SE-CTG', '2026 July Chattogram flooding (extended recession)', 'Chattogram', '2026-07-22', '2026-07-24', 'low', 'flash_flood', 'Chattogram still worst-hit on 25 Jul per BSS; end approximated', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-T1', '2026 mid-July Teesta rise', 'Lalmonirhat;Nilphamari', '2026-07-13', '2026-07-15', 'low', 'river_flood', 'bdnews24 13 Jul 2026: Teesta above danger mark; fresh floods threaten northern districts', 'https://bdnews24.com/bangladesh/a29bac4ee374 | https://thefinancialexpress.com.bd/national/teesta-rises-above-danger-mark-as-fresh-floods-threaten-northern-districts'),
('BDF-2026-07-T2', '2026 late-July Teesta flooding and embankment breaches', 'Lalmonirhat;Rangpur', '2026-07-22', '2026-07-24', 'low', 'river_flood', '22 Jul: Teesta 1cm below danger at Dalia, water in Lalmonirhat upazilas; Gangachara (Rangpur) embankments breached, ~10,000 stranded', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-07-X', '2026 July wider flooding (secondary districts)', 'Brahmanbaria;Cumilla;Sylhet;Sunamganj', '2026-07-08', '2026-07-19', 'low', 'flash_flood', 'Agriculture ministry puts Brahmanbaria among 7 worst-hit; Cumilla crops affected; Sylhet division inundated per news summaries; dates approximated', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/ | https://dailynewnation.com/news/843812'),
('BDF-2026-08-CTG', '2026 August Chattogram urban waterlogging', 'Chattogram', '2026-08-17', '2026-08-17', 'medium', 'urban_waterlogging', '167-189mm in 24h on 17 Aug, knee-deep water in many neighbourhoods (Business Standard, Daily Star)', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-08-HB1', '2026 August Khowai crossing (Habiganj)', 'Habiganj', '2026-08-12', '2026-08-12', 'low', 'flash_flood', 'Khowai at Ballah 20cm above danger on 12 Aug, back under on 13 Aug', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-08-HB2', '2026 late-August Khowai flood and Kaliganj embankment breach (Habiganj)', 'Habiganj', '2026-08-23', '2026-08-25', 'medium', 'flash_flood', 'Khowai 130cm above danger on 23 Aug; embankment breach flooded 22 villages (~4,500 families); back under danger 25 Aug', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-08-NE', '2026 August Kushiyara above danger (Sylhet)', 'Sylhet', '2026-08-05', '2026-08-16', 'low', 'river_flood', 'Kushiyara at Fenchuganj above danger 5-16 Aug (11-23cm over); flooding of low ground along the river', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-08-T', '2026 early-August Teesta flood', 'Lalmonirhat', '2026-08-05', '2026-08-07', 'medium', 'river_flood', 'Teesta 13cm above danger at Dalia on 5 Aug; Dahagram (Patgram) ~3,000 families affected on 6 Aug', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/ | https://www.thedailystar.net/news/monsoon-misery/news/10-districts-likely-face-short-term-floods-next-24-48-hours-ffwc-4240816'),
('BDF-2026-08-T2', '2026 early-August Teesta flood (neighbouring districts)', 'Nilphamari;Gaibandha', '2026-08-05', '2026-08-07', 'low', 'river_flood', 'Teesta above danger at Dalia (Nilphamari) 5-6 Aug and 13cm above at Tarapur (Gaibandha) 6 Aug', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/'),
('BDF-2026-09-RJ', '2026 September Padma char flooding (Rajshahi)', 'Rajshahi', '2026-09-02', '2026-09-10', 'low', 'river_flood', '~300-350 families on Padma chars (Paba) marooned for about a week before relocation on 9 Sep', 'https://www.mappr.co/bangladesh-monsoon-floods-2026/');
